def product_card(p):
 name=esc(p['name']);short=esc(p['short']);cat=esc(p['category'])
 return f'''<article class="product-card" data-product-card data-category="{p['categoryKey']}" data-search="{esc(p['name']+' '+p['short']+' '+p['category'],quote=True)}">
<a href="/products/{p['slug']}/" aria-label="Explore {name}">{art(p)}</a><div class="product-body"><div class="product-meta"><span class="product-category">{cat}</span><span class="product-tag" data-product-status="{p['slug']}">{esc(p['tag'])}</span></div><h3><a href="/products/{p['slug']}/">{name}</a></h3><p>{short}</p><div class="product-bottom"><span class="price">£{p['price']}<small>Planned launch price</small></span><a class="card-link" href="/products/{p['slug']}/">See details {icon('arrow',16)}</a></div></div></article>'''

