resources=page_hero('A little head start, on us.','Explore practical AI prompts you can use today. Our free starter pack is ready to download, no sign-up or payment required.','Free resources')+f'''<section class="section"><div class="container two-col"><div>{sectionlabel('Free starter resource')}<h2 class="heading-md">20 useful prompts for real business days.</h2><p class="lead">From writing customer replies to planning social posts, these simple prompts help you take a useful first step with AI.</p><div class="chip-line" style="margin:23px 0"><span class="pill green">100% free</span><span class="pill soft">Plain text • 5 KB</span><span class="pill soft">No sign-up</span></div><a class="btn btn-primary" href="/downloads/20-ai-prompts-for-small-business.txt" download>Download the 20 prompts {icon('download')}</a><p class="detail-notice">You can open the .txt file in any text editor and copy prompts into your chosen AI assistant.</p></div><div class="illustration-panel"><div class="illust-center"><span class="illust-circle">{icon('sparkles',54)}</span><strong>A better starting point.</strong><small>20 prompts, countless ideas.</small></div></div></div></section><section class="section products-section"><div class="container">{sectionlabel('Try these now')}<h2 class="heading-md">A few favourites from the pack.</h2><p class="subheading">Tap copy, add your details and give the prompt a try. Always check the result before using it.</p><div class="prompt-list">{''.join(f'<article class="prompt-item"><div class="prompt-top"><h3>{esc(title)}</h3><button class="copy-btn" type="button" data-copy-text="{esc(content,quote=True)}">Copy prompt</button></div><p>{esc(content)}</p></article>' for title,content in samples)}</div></div></section><section class="section-sm"><div class="container"><div class="dark-cta"><div>{sectionlabel('Where to next?')}<h2>Ready for a more complete toolkit?</h2><p>See what we are creating for small businesses in specific industries.</p></div>{btn('Browse upcoming products','/shop/','btn-light')}</div></div></section>'''
page('Free AI prompts & resources','Download 20 free practical AI prompts for small business owners. No sign-up required.',resources,active='resources',path='/resources/')

# faq
morefaq=faq_items+[('How do I receive a purchase?','Once a product is released, secure payment and file delivery will take place through Payhip. The checkout link will be provided on the product page.'),('Can I edit the templates?','We plan to include editable formats where appropriate. Each product page will describe exactly what files it contains before sales are enabled.'),('Can I resell or share a purchased toolkit?','Unless an individual product licence explicitly allows it, digital resources will be licensed for use by the purchaser and must not be resold, redistributed or shared as standalone products.'),('Do you offer refunds?','See the refund policy for the intended process. Final sales terms will be published before checkout is activated, and your statutory consumer rights will be respected.'),('Do I need a paid ChatGPT plan?','Some tasks may work on free AI plans, though provider features and limitations can change. We will describe any special requirements on each product page.'),('How do I contact BlueHatch Digital?','Use the Contact page. A working business email address will be published before the store opens.')]
