# contact
contactpage=page_hero('We would love to hear from you.','Have a question, an idea or a business challenge you want a toolkit for? Get in touch.','Contact')+f'''<section class="section"><div class="container contact-grid"><div><div class="contact-card"><span class="value-icon">{icon('mail',24)}</span><h3>Say hello.</h3><p>We are preparing our first collection. If you have a question or would like to suggest a future toolkit, send us a message.</p><p><strong>Business email</strong><br><a data-email-link>Available at launch</a></p><p style="font-size:12px">Before launch, we'll connect the contact address to the form on this page.</p></div></div><div><h2 class="heading-md" style="margin-top:0">Send an enquiry.</h2><form class="contact-form" data-contact-form><div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" placeholder="Your name" required maxlength="120"></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" required maxlength="200"></div><div class="field"><label for="subject">What is this about?</label><select id="subject" name="subject"><option>General enquiry</option><option>Product question</option><option>Product idea</option><option>Partnership</option></select></div><div class="field"><label for="message">Your message</label><textarea id="message" name="message" placeholder="Tell us what is on your mind..." required maxlength="5000"></textarea></div><div><button class="btn btn-primary" type="submit">Prepare email {icon('arrow')}</button></div><p class="form-feedback" data-form-feedback>When the business email is configured, submitting this form will open your email app. It does not send automatically.</p></form></div></div></section>'''
page('Contact us','Get in touch with BlueHatch Digital with questions, product ideas or feedback.',contactpage,path='/contact/')

# Plain-language starter policies, marked review required
legal_data={
 'privacy':('Privacy policy','How we handle personal information on this website.','''<div class="notice"><strong>Draft policy — review before launch.</strong> Replace missing company details, confirm all services you actually use, and obtain appropriate legal review before taking payments or collecting customer data.</div>
<h2>1. Who we are</h2><p>This website is being prepared under the working name BlueHatch Digital. Our business identity and contact email will be confirmed before launch.</p>
<h2>2. Information collected by this site</h2><p>This version of the website does not operate its own analytics, tracking cookies or mailing list. The contact form opens your email application locally; information is only sent if you choose to send the prepared email.</p>
<h2>3. Payment partners</h2><p>Once products go live, purchases may take place through Payhip. Payhip operates its own checkout and processes customer information in accordance with its own published privacy terms.</p>
<h2>4. Hosting and technical information</h2><p>Our hosting provider may process basic connection and security data, such as IP addresses and access logs, to deliver the site and prevent abuse. Final hosting arrangements will be confirmed at launch.</p>
<h2>5. Your rights</h2><p>Depending on applicable law, you may have rights to access, correct, erase, restrict or object to processing of your personal data. Use the published contact details to make a request.</p>
<h2>6. Changes</h2><p>We will update this policy as the website evolves and publish a clear effective date.</p>'''),
 'terms':('Website terms','The intended terms for browsing and using BlueHatch Digital resources.','''<div class="notice"><strong>Draft terms — not final sales terms.</strong> Please review, complete the business identity details and adapt these terms before activating purchases.</div>
<h2>1. About this website</h2><p>BlueHatch Digital is a proposed digital products business. The products shown are previews until a product page links to a functioning checkout service.</p>
<h2>2. Information and AI-assisted resources</h2><p>Information on this site is general educational material, not personalised legal, financial, medical or other professional advice. AI outputs can contain errors and should be checked before use.</p>
<h2>3. Intellectual property</h2><p>Website text, graphics and original resources are intended to be protected by applicable intellectual property rights. Do not copy, redistribute or resell purchased materials except as permitted by their individual licence.</p>
<h2>4. Products and pricing</h2><p>Listed prices are planned launch prices and may change before release. Product format, access instructions, licence terms and final price will be confirmed before payment.</p>
<h2>5. Third-party services</h2><p>External payment, marketplace and AI platforms operate under their own terms. BlueHatch Digital does not control their availability or policies.</p>
<h2>6. Contact</h2><p>Contact information will be added before the store begins selling.</p>'''),
 'refunds':('Refund & digital downloads policy','How we plan to handle digital products, delivery and requests for support.','''<div class="notice"><strong>Pre-launch draft — legal review required.</strong> This policy is an outline only and must be finalised, including digital-content cancellation consent, before accepting purchases from UK consumers.</div>
<h2>1. Product delivery</h2><p>When purchases are enabled, downloadable products will be delivered through the chosen checkout and delivery provider, expected to be Payhip.</p>
<h2>2. Before you purchase</h2><p>Each product page will explain the included files, supported formats, access requirements and licence before checkout is enabled.</p>
<h2>3. If something is wrong</h2><p>If a purchased file is inaccessible, corrupted, materially not as described or otherwise faulty, customers should contact us so we can investigate and provide an appropriate remedy.</p>
<h2>4. Cancellations and refunds</h2><p>Digital downloads can be subject to different cancellation rules from physical goods. Any cancellation-right waiver must comply with applicable consumer law and requires appropriate express consent where relevant. Nothing in our terms removes statutory consumer rights.</p>
<h2>5. Contact information</h2><p>A customer-support email and final process will be published before sales begin.</p>''')
}
for slug,(title,desc,body) in legal_data.items():
 content=page_hero(esc(title),esc(desc),'Legal')+f'<section class="section"><div class="container prose">{body}</div></section>'
 page(title,desc,content,path='/legal/'+slug+'/')

